// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.Test;

import com.fasterxml.jackson.databind.JsonNode;

import io.swagger.v3.core.util.Json;

public class IdentitySecurityContractTest {

    private JsonNode document;
    private JsonNode paths;

    @Test
    public void identityDiscoveryEndpointsDoNotRequireAuthentication() throws Exception {
        givenGeneratedDocument();

        whenIdentityDiscoveryEndpointsAreRead();

        thenIdentityDiscoveryEndpointsArePublic();
        thenIdentityMutationsInheritAuthentication();
    }

    @Test
    public void securityVersionsExposeDistinctOperations() throws Exception {
        givenGeneratedDocument();

        whenSecurityEndpointsAreRead();

        thenInheritedOperationsHaveVersionedIdentifiers();
        thenPolicyUploadHasRequiredTextBody();
    }

    @Test
    public void conflictResponsesDocumentErrorBodies() throws Exception {
        givenGeneratedDocument();

        whenIdentityConflictsAreRead();

        thenConflictsReferenceTheErrorSchema();
    }

    private void givenGeneratedDocument() throws Exception {
        this.document = Json.mapper()
                .readTree(Files.readString(Path.of(System.getProperty("openapi.directory"), "openapi.json")));
    }

    private void whenIdentityDiscoveryEndpointsAreRead() {
        this.paths = this.document.path("paths");
    }

    private void whenSecurityEndpointsAreRead() {
        this.paths = this.document.path("paths");
    }

    private void whenIdentityConflictsAreRead() {
        this.paths = this.document.path("paths");
    }

    private void thenConflictsReferenceTheErrorSchema() {
        for (String path : new String[] { "/identity/v2/identities", "/identity/v2/permissions" }) {
            JsonNode conflict = this.paths.path(path).path("post").path("responses").path("409");
            assertEquals(path, "#/components/schemas/Error",
                    conflict.path("content").path("application/json").path("schema").path("$ref").asText());
        }
    }

    private void thenIdentityDiscoveryEndpointsArePublic() {
        for (String path : new String[] { "/identity/v1/definedPermissions", "/identity/v1/passwordRequirements",
                "/identity/v2/definedPermissions", "/identity/v2/passwordStrenghtRequirements" }) {
            JsonNode operation = this.paths.path(path).path("get");
            assertTrue(path, operation.has("security"));
            assertEquals(path, 0, operation.path("security").size());
        }
    }

    private void thenIdentityMutationsInheritAuthentication() {
        for (String path : new String[] { "/identity/v1/identities", "/identity/v2/identities" }) {
            assertFalse(path, this.paths.path(path).path("post").has("security"));
        }
    }

    private void thenInheritedOperationsHaveVersionedIdentifiers() {
        for (String version : new String[] { "v1", "v2" }) {
            JsonNode operation = this.paths.path("/security/" + version + "/debug-enabled").path("get");
            assertEquals("get_security_" + version + "_debug_enabled", operation.path("operationId").asText());
            assertFalse(operation.has("security"));
        }
    }

    private void thenPolicyUploadHasRequiredTextBody() {
        JsonNode operation = this.paths.path("/security/v2/security-policy/apply").path("post");
        JsonNode body = operation.path("requestBody");
        assertTrue(body.path("required").asBoolean());
        assertEquals("string", body.path("content").path("text/plain").path("schema").path("type").asText());
        assertTrue(operation.path("responses").has("200"));
        assertTrue(operation.path("responses").has("400"));
    }
}
